import com.sun.source.tree.*;
import com.sun.source.util.*;
import javax.tools.*;
import java.nio.file.*;
import java.util.*;

/** Parse-only syntax/scope inventory; does not claim whole-project attribution/compilation. */
public final class SourceInventory {
 static final List<Object> classes=new ArrayList<>(),calls=new ArrayList<>(),declarations=new ArrayList<>();
 static Map<String,Object> obj(Object... a){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)m.put((String)a[i],a[i+1]);return m;}
 static String json(Object v){if(v==null)return "null";if(v instanceof Map){List<String> a=new ArrayList<>();for(Object e0:((Map<?,?>)v).entrySet()){Map.Entry<?,?> e=(Map.Entry<?,?>)e0;a.add(json(e.getKey())+":"+json(e.getValue()));}return "{"+String.join(",",a)+"}";}if(v instanceof Iterable){List<String>a=new ArrayList<>();for(Object e:(Iterable<?>)v)a.add(json(e));return "["+String.join(",",a)+"]";}if(v instanceof Number||v instanceof Boolean)return v.toString();StringBuilder b=new StringBuilder("\"");for(char c:v.toString().toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<' ')b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
 static class Scan extends TreePathScanner<Void,Void>{
  CompilationUnitTree cu;SourcePositions positions;String text,path,pkg;Map<String,String> imports=new LinkedHashMap<>();Deque<String> owners=new ArrayDeque<>();Deque<Map<String,Object>> scopes=new ArrayDeque<>();MethodTree method;VariableTree field;
  Scan(CompilationUnitTree c,Trees trees,Path root)throws Exception{cu=c;positions=trees.getSourcePositions();text=c.getSourceFile().getCharContent(true).toString();path=root.relativize(Paths.get(c.getSourceFile().toUri())).toString();pkg=c.getPackageName()==null?"":c.getPackageName().toString();for(ImportTree i:c.getImports())if(!i.isStatic()){String n=i.getQualifiedIdentifier().toString();imports.put(n.substring(n.lastIndexOf('.')+1),n);}}
  String src(Tree t){long a=positions.getStartPosition(cu,t),b=positions.getEndPosition(cu,t);return a<0||b<0?t.toString():text.substring((int)a,(int)b);}
  long at(Tree t){return positions.getStartPosition(cu,t);}
  String type(Tree t){if(t==null)return null;String n=t.toString().replaceAll("<.*>","");if(n.contains("."))return n;return imports.containsKey(n)?imports.get(n):pkg+"."+n;}
  void push(){scopes.push(new LinkedHashMap<String,Object>());} void pop(){scopes.pop();}
  @Override public Void visitClass(ClassTree t,Void v){String name=t.getSimpleName().toString();String parentType=type(t.getExtendsClause());if(name.isEmpty()){Tree p=getCurrentPath().getParentPath().getLeaf();if(p instanceof NewClassTree)parentType=type(((NewClassTree)p).getIdentifier());name="anonymous_at_"+at(t);}String owner=owners.isEmpty()?pkg+"."+name:owners.peek()+"."+name;List<Object> fields=new ArrayList<>();for(Tree m:t.getMembers())if(m instanceof VariableTree){VariableTree f=(VariableTree)m;fields.add(obj("name",f.getName().toString(),"type",type(f.getType()),"source",src(f),"start",at(f)));}classes.add(obj("owner",owner,"parent",parentType,"path",path,"fields",fields,"start",at(t)));owners.push(owner);Deque<Map<String,Object>> old=scopes;scopes=new ArrayDeque<>();push();super.visitClass(t,v);scopes=old;owners.pop();return null;}
  @Override public Void visitMethod(MethodTree t,Void v){MethodTree old=method;method=t;push();if(t.getName().toString().contains("isBlockIndirectlyGettingPowered")||t.getName().toString().equals("isBlockPowered"))declarations.add(obj("owner",owners.peek(),"path",path,"source",src(t)));super.visitMethod(t,v);pop();method=old;return null;}
  @Override public Void visitBlock(BlockTree t,Void v){push();super.visitBlock(t,v);pop();return null;}
  @Override public Void visitForLoop(ForLoopTree t,Void v){push();super.visitForLoop(t,v);pop();return null;}
  @Override public Void visitEnhancedForLoop(EnhancedForLoopTree t,Void v){push();super.visitEnhancedForLoop(t,v);pop();return null;}
  @Override public Void visitCatch(CatchTree t,Void v){push();super.visitCatch(t,v);pop();return null;}
  @Override public Void visitLambdaExpression(LambdaExpressionTree t,Void v){push();super.visitLambdaExpression(t,v);pop();return null;}
  @Override public Void visitVariable(VariableTree t,Void v){Tree parent=getCurrentPath().getParentPath().getLeaf();boolean isField=parent instanceof ClassTree;VariableTree old=field;if(isField)field=t;else if(!scopes.isEmpty())scopes.peek().put(t.getName().toString(),obj("type",type(t.getType()),"source",src(t),"start",at(t),"parent_kind",parent.getKind().toString()));super.visitVariable(t,v);field=old;return null;}
  @Override public Void visitMethodInvocation(MethodInvocationTree t,Void v){String n=t.getMethodSelect().toString();if(n.endsWith(".isBlockIndirectlyGettingPowered")||n.endsWith(".isBlockPowered")){Map<String,Object> vars=new LinkedHashMap<>();List<Map<String,Object>> all=new ArrayList<>(scopes);Collections.reverse(all);for(Map<String,Object>s:all)vars.putAll(s);List<Object> args=new ArrayList<>();for(ExpressionTree arg:t.getArguments())args.add(src(arg));calls.add(obj("path",path,"owner",owners.peek(),"start",at(t),"end",positions.getEndPosition(cu,t),"line",cu.getLineMap().getLineNumber(at(t)),"source",src(t),"receiver",src(((MemberSelectTree)t.getMethodSelect()).getExpression()),"arguments",args,"locals",vars,"method",method==null?null:src(method),"field",field==null?null:src(field)));}return super.visitMethodInvocation(t,v);}
 }
 public static void main(String[] a)throws Exception{Path root=Paths.get(a[0]).toAbsolutePath();JavaCompiler c=ToolProvider.getSystemJavaCompiler();StandardJavaFileManager fm=c.getStandardFileManager(null,null,java.nio.charset.StandardCharsets.UTF_8);List<java.io.File> files=new ArrayList<>();Files.walk(root).filter(p->p.toString().endsWith(".java")).sorted().forEach(p->files.add(p.toFile()));DiagnosticCollector<JavaFileObject> diagnostics=new DiagnosticCollector<>();JavacTask task=(JavacTask)c.getTask(null,fm,diagnostics,Arrays.asList("-proc:none","-source","8"),null,fm.getJavaFileObjectsFromFiles(files));Iterable<? extends CompilationUnitTree> parsed=task.parse();Trees trees=Trees.instance(task);for(CompilationUnitTree cu:parsed)new Scan(cu,trees,root).scan(cu,null);for(Diagnostic<?> d:diagnostics.getDiagnostics())if(d.getKind()==Diagnostic.Kind.ERROR)throw new IllegalStateException(d.toString());System.out.println(json(obj("classes",classes,"calls",calls,"declarations",declarations)));fm.close();}
}
